INSERT INTO "public"."supplier_analysis" ("id", "supplier_name", "url", "business_type", "identified_activities", "hs_code_matches", "created_at", "business_evidence", "expected_tier", "primary_tier", "primary_tier_confidence", "primary_tier_evidence", "additional_tiers", "duns", "wgr_165", "source") VALUES ('11', 'MB Tool', 'http://www.mbtool.cz', 'PARTS_MANUFACTURER', '[{"activity": "Product Development", "evidence": "\\"Vývoj Od roku 2010, kdy jsme se stali oficiálním vývojovým partnerem skupiny Volkswagen, se ve spolupráci s našimi zákazníky věnujeme kromě výroby komponent i komplexnímu vývoji výrobku. Jaké oblasti vývoje realizujeme? Konstrukce dílu Simulace a výpočty Výroba prototypů 3D měření Zkoušky a testy\\""}, {"activity": "Mold Making", "evidence": "\\"Formy MB TOOL s.r.o. disponuje moderní nástrojárnou, nejnovějšími technologiemi a týmem odborných pracovníků. ... CNC obrábění ve 3 až 5-ti osách ovládáme v oblasti frézování, soustružení, EDM erodování a drátování... optimalizace a technické změny dílu realizujeme i díky mj. vlastnímu laserovému navařování.\\""}, {"activity": "Plastic Part Production", "evidence": "\\"Sériová produkce Plastové díly / Montáže / Zpracování přírodní úsně / Sériové obrábění kovů Plastové díly V našich lisovnách vyrábíme plastové díly z termoplastických materiálů na vstřikovacích strojích o velikosti 50-1600 tun s možností vstřikování výlisků do hmotnosti 1500 g.\\""}, {"activity": "Assembly of Automotive Interior Components", "evidence": "\\"Montáže V návaznosti na výrobu forem a lisování plastových dílů přirozeně navazujeme montáží finálních kompletů a sestav dílů, které nacházejí uplatnění v interiéru automobilu. Co a jak tedy montujeme? řadící páky, ruční brzdy, odkládací schránky ve střední konzole a stropě, kompletní střední konzole, obložení volantů, okolí zpětných zrcátek provádíme ruční i robotizovanou montáž\\""}, {"activity": "Natural Leather Processing", "evidence": "\\"Zpracování přírodní úsně Mimo montáží sestav plastových dílů se specializujeme na produkci dílů, které jsou jakkoliv dotčeny přírodní kůží.\\""}, {"activity": "Testing and Quality Control", "evidence": "\\"Kontrola kvality Pro kontrolu a měření používáme nejnovější technologie měření. Kvalita našich výrobků je mimo jiné prověřována pomocí těchto zařízení: ROZMĚRY 3D souřadnicový měřící stroj vybavený indexovatelnou měřící soundou a optickou kamerou MECHANICKÉ VLASTNOSTI trhačka materiálu pro měření pevnosti materiálu v tahu a tlaku TEPELNÁ ODOLNOST klimatická komora +90°C / -40°C vč. normy PV 1200 VISKOZITA MATERIÁLU MFI přistroj pro měření indexu toku taveniny ODSTÍNY A LESKY digitální spektrofotometr EXTERNÍ ZKOUŠKY\\""}]', '[{"tier": "TIER1", "hsCode": "8708", "evidence": "\\"Co a jak tedy montujeme? řadící páky, ruční brzdy, odkládací schránky ve střední konzole a stropě, kompletní střední konzole, obložení volantů, okolí zpětných zrcátek\\"", "reasoning": "The company produces interior automotive components such as gear levers, handbrakes, center consoles, and steering wheel trims, which are parts and accessories of motor vehicles.", "confidence": "MEDIUM"}, {"tier": "TIER2", "hsCode": "3920", "evidence": "\\"Sériová produkce Plastové díly / Montáže / Zpracování přírodní úsně / Sériové obrábění kovů Plastové díly V našich lisovnách vyrábíme plastové díly z termoplastických materiálů\\"", "reasoning": "The company produces plastic parts from thermoplastic materials, which can be classified under HS code 3920 as ''Other plates, sheets, film, foil and strip, of plastics, non-cellular and not reinforced, laminated, supported or similarly combined with other materials''.", "confidence": "MEDIUM"}, {"tier": "TIER2", "hsCode": "4011", "evidence": "\\"Přehled produktů prototypové a sériové nástroje formy do hmotnosti 4500 kg nástroje pro plast a pryž, střižné nástroje kontrolní a měřící přípravky montážní přípravky\\"", "reasoning": "While the company processes rubber for tools, there is no explicit mention of producing tires. Therefore, a match with HS code 4011 (New pneumatic tyres, of rubber) is not supported by explicit evidence.", "confidence": "INSUFFICIENT_EVIDENCE"}, {"tier": "TIER3", "hsCode": "3901", "evidence": "\\"Plastové díly V našich lisovnách vyrábíme plastové díly z termoplastických materiálů\\"", "reasoning": "The company uses thermoplastic materials for plastic parts production, which can include polymers of ethylene, propylene, styrene, or vinyl chloride, potentially falling under HS codes 3901, 3902, 3903, or 3904.  Without specifying the exact type of polymers, 3901 (Polymers of ethylene, in primary forms) serves as a general example for plastics.", "confidence": "MEDIUM"}]', '2025-02-13 19:17:18.769984+00', 'Sériová produkce Plastové díly / Montáže / Zpracování přírodní úsně / Sériové obrábění kovů Plastové díly V našich lisovnách vyrábíme plastové díly z termoplastických materiálů na vstřikovacích strojích o velikosti 50-1600 tun s možností vstřikování výlisků do hmotnosti 1500 g.', 'TIER1', 'TIER1', 'HIGH', 'Montáže V návaznosti na výrobu forem a lisování plastových dílů přirozeně navazujeme montáží finálních kompletů a sestav dílů, které nacházejí uplatnění v interiéru automobilu. Co a jak tedy montujeme? řadící páky, ruční brzdy, odkládací schránky ve střední konzole a stropě, kompletní střední konzole, obložení volantů, okolí zpětných zrcátek provádíme ruční i robotizovanou montáž', '[]', '', '100', '1'), ('12', 'Adis Tachov', 'https://www.adistachov.cz', 'PARTS_MANUFACTURER', '[{"activity": "Injection Molding", "evidence": "\\"Injection Molding custom molding, pad printing, over-molding and insert molding.\\""}, {"activity": "Mold and Tooling Design, Build, Repair, Maintenance, Modification", "evidence": "\\"We design, build, repair, maintain and modify custom molds and toolings.\\""}, {"activity": "Assembly", "evidence": "\\"assembly, packaging, worldwide Shipping, and additional turnkey needs.\\""}, {"activity": "Production of plastic parts for automotive industry", "evidence": "\\"Producing millions of plastic parts annually for the automotive industry\\""}, {"activity": "Ultrasonic welding", "evidence": "\\"We also offer ultrasonic welding, assembly, metal to plastic conversion, FDM-3D prototype, program management, and exceptional quality assurance.\\""}, {"activity": "Metal to plastic conversion", "evidence": "\\"We also offer ultrasonic welding, assembly, metal to plastic conversion, FDM-3D prototype, program management, and exceptional quality assurance.\\""}, {"activity": "FDM-3D prototype", "evidence": "\\"We also offer ultrasonic welding, assembly, metal to plastic conversion, FDM-3D prototype, program management, and exceptional quality assurance.\\""}]', '[{"tier": "TIER2", "hsCode": "392099", "evidence": "\\"Producing millions of plastic parts annually for the automotive industry\\", \\"all your plastic needs\\"", "reasoning": "Manufacturing of plastic parts implies use of plastic sheets or films, which could fall under HS code 3920 ''Other plates, sheets, film, foil and strip, of plastics''. Sub-category 392099 ''Of other plastics'' is used as a broad match for unspecified plastic parts.", "confidence": "MEDIUM"}]', '2025-02-13 19:20:08.240188+00', '"Producing millions of plastic parts annually for the automotive industry"', 'TIER1', 'TIER2', 'MEDIUM', '"Producing millions of plastic parts annually for the automotive industry", "injection-molded, and assembled components"', '[]', '', '100', '1'), ('14', 'BOS', 'https://www.bos.de', 'PARTS_MANUFACTURER', '[{"activity": "Designs and produces mechatronics, kinematics and plastic systems", "evidence": "\\"BOS designs and produces innovative mechatronics, kinematics and plastic systems for automobiles\\""}, {"activity": "Manufactures luggage covers", "evidence": "\\"Luggage Covers for hatchback vehicles, station wagons, vans and modern SUV I CUV\\""}, {"activity": "Manufactures optical and thermal shading systems", "evidence": "\\"Optical and thermal shading systems for transparent glass surfaces in vehicles.\\""}, {"activity": "Manufactures panoramic roof systems", "evidence": "\\"Panoramic roof systems for modern vehicles - fixed or to be opened\\""}, {"activity": "Produces upholstery and trim parts", "evidence": "\\"Upholstery and trim parts produced in countries with leading cost structures.\\""}, {"activity": "Manufactures intelligent trunk storage systems", "evidence": "\\"Intelligent Trunk Storage, Fixation and Organization Systems\\""}, {"activity": "Manufactures load restraining and passenger protection systems", "evidence": "\\"Load restraining and passenger protection in case of braking or crash.\\""}, {"activity": "Manufactures roof and rear carrier systems", "evidence": "\\"Roof and rear carrier systems as original vehicle equipment or specialized shop parts.\\""}, {"activity": "Uses injection molding, blow molding and extrusion", "evidence": "\\"Injection molding, blow molding and extrusion for modern light weight elements in the vehicle engine.\\""}, {"activity": "CNC cutting of leather and textiles", "evidence": "\\"Continuous innovations and improvements lead to exceptional know-how in the area of CNC cutting of leather and textiles\\""}, {"activity": "Sequential assembly", "evidence": "\\"Continuous innovations and improvements lead to exceptional know-how ... in sequential assembly.\\""}, {"activity": "Operates prototype shop", "evidence": "\\"prototype shop, test facilities\\""}, {"activity": "Operates test facilities", "evidence": "\\"prototype shop, test facilities\\""}, {"activity": "Quality Management certified IATF 16949 and EN-ISO 9001", "evidence": "\\"Our internationally certified Quality Management (IATF 16949 and EN-ISO 9001) guarantees the highest quality standards at every BOS site.\\""}, {"activity": "Environmental management system DIN EN ISO 14001", "evidence": "\\"BOS assumes social responsibility with an environmentally sound design of all operations and processes according to the environmental management system DIN EN ISO 14001.\\""}, {"activity": "Purchasing and supplier management in China", "evidence": "\\"Purchasing and supplier management in China are performed from our International Purchasing Office in Shanghai.\\""}, {"activity": "Employ quality engineers", "evidence": "\\"quality enginners in our Shanghai office ensure that the BOS Group is supplied with cost optimized and demand meeting components from China.\\""}, {"activity": "Technical analysis of non-conforming parts", "evidence": "\\"Provádí technickou analytickou činnost při výskytu neshodných dílů\\""}, {"activity": "Manages quality claims with suppliers", "evidence": "\\"Zajišťuje reklamační řízení na dodavatele\\""}, {"activity": "Defines measures to eliminate quality risks from suppliers", "evidence": "\\"Definuje a zavádí nutná opatření na straně dodavatele s cílem eliminace rizik spojených s nakupovanými díly\\""}, {"activity": "Organizes sorting of non-conforming production", "evidence": "\\"Organizuje třídění neshodné výroby\\""}, {"activity": "Verifies parts against technical drawings", "evidence": "\\"Ověřuje díly z produkce dle výkresové dokumentace\\""}, {"activity": "Conducts tests and measurements according to control plans and technical drawings", "evidence": "\\"Provádí zkoušky a měření dle kontrolního plánu / výkresové dokumentace\\""}]', '[{"tier": "TIER1", "hsCode": "9401", "product": "Luggage Covers, Upholstery and trim parts", "evidence": "\\"Luggage Covers for hatchback vehicles, station wagons, vans and modern SUV I CUV\\"", "reasoning": "Luggage covers, upholstery and trim parts are related to vehicle seats and interior parts.", "confidence": "HIGH"}, {"tier": "TIER1", "hsCode": "8708", "product": "Panoramic roof systems, Optical and thermal shading systems", "evidence": "\\"Panoramic roof systems for modern vehicles - fixed or to be opened\\"", "reasoning": "Panoramic roof systems and optical/thermal shading systems can be considered parts and accessories for motor vehicles.", "confidence": "MEDIUM"}, {"tier": "TIER3", "hsCode": "3920", "product": "Plastic systems", "evidence": "\\"plastic systems for automobiles\\"", "reasoning": "Plastic systems and manufacturing processes like injection molding, blow molding and extrusion suggest plastic components.", "confidence": "MEDIUM"}, {"tier": "TIER1", "hsCode": "870821", "product": "Load restraining and passenger protection systems", "evidence": "\\"Load restraining and passenger protection in case of braking or crash.\\"", "reasoning": "Load restraining and passenger protection systems are related to safety within vehicles, potentially including safety seat belts or similar systems.", "confidence": "MEDIUM"}]', '2025-02-13 19:34:06.680454+00', '"BOS designs and produces innovative mechatronics, kinematics and plastic systems for automobiles"', 'TIER1', 'TIER1', 'HIGH', '"Roof and rear carrier systems as original vehicle equipment"', '[{"tier": "TIER3", "evidence": "\\"plastic systems for automobiles\\"", "confidence": "MEDIUM"}]', '', '100', '1'), ('15', 'Flidr Plast', 'https://flidr.cz', 'PARTS_MANUFACTURER', '[{"activity": "CNC obráběné díly", "evidence": "\\"CNC obráběné díly.\\""}, {"activity": "Výroba rámů hlavových opěr", "evidence": "\\"RÁMY HLAVOVÝCH OPĚR V sériové výrobě hlavových opěr... Průměrná roční produkce rámů hlavových opěr přesahuje 5 milionů kusů.\\""}, {"activity": "Výroba plastových dílů pro automobilový průmysl (plastové boxy hlavových opěr, rámy loketních opěr, kryty světel, zámků, rámečky a krytky do kufrů)", "evidence": "\\"PLASTOVÉ DÍLY Mezi nejdůležitější vstřikované díly vyráběné pro automobilový průmysl patří mimo jiné plastové boxy hlavových opěr, rámy loketních opěr, kryty světel, zámků, rámečky a krytky do kufrů.\\""}, {"activity": "Výroba krytů zavazadlového prostoru", "evidence": "\\"KRYTY ZAVAZADLOVÉHO PROSTORU Nejnovějším přírůstkem v portfoliu výroby pro automobilový průmysl je od roku 2019 také kryt zavazadlového prostoru.\\""}, {"activity": "Vstřikování plastů", "evidence": "\\"vstřikované díly\\""}, {"activity": "Obstřikování plastů", "evidence": "\\"zastřikované díly\\""}, {"activity": "CELL MOULD technology", "evidence": "\\"Disponujeme technologií CELL MOULD\\""}, {"activity": "Ultrazvukové svařování", "evidence": "\\"ultrazvukovým svařováním.\\""}, {"activity": "Infračervené svařování", "evidence": "\\"infračerveným svařováním.\\""}, {"activity": "Obstřikování kovových dílů", "evidence": "\\"Umíme obstřik kovových dílů.\\""}, {"activity": "Výroba dílů s vysokou rozměrovou i tvarovou přesností", "evidence": "\\"Vyrábíme díly s vysokou rozměrovou i tvarovou přesností\\""}, {"activity": "Zpracování termoplastů a termoplastických elastomerů", "evidence": "\\"Zpracováváme všechny typy termoplastů a termoplastických elastomerů.\\""}, {"activity": "Simulační analýzy procesu vstřikování", "evidence": "\\"Nabízíme vypracování simulační analýzy procesu vstřikování v rozsahu dle požadavků zákazníka.\\""}, {"activity": "Výroba a montáž ocelových a hliníkových konstrukcí pro fotovoltaické elektrárny", "evidence": "\\"Od roku 2022 vyrábíme a montujeme ocelové žárově zinkované nebo hliníkové konstrukce pro fotovoltaické elektrárny.\\""}, {"activity": "Třískové obrábění kovových i nekovových dílců", "evidence": "\\"Třískové obrábění kovových i nekovových dílců\\""}, {"activity": "Tváření materiálu za studena", "evidence": "\\"Tváření materiálu za studena\\""}, {"activity": "Stříhání, ohýbání a lisování kovových dílců", "evidence": "\\"Stříhání, ohýbání a lisování kovových dílců\\""}, {"activity": "Svařování v ochranné atmosféře CO2 a argonu", "evidence": "\\"Svařování v ochranné atmosféře CO2 a argonu\\""}, {"activity": "Vibrační a odstředivé leštění a broušení kovových a nekovových dílců", "evidence": "\\"Vibrační a odstředivé leštění a broušení kovových a nekovových dílců\\""}, {"activity": "Elektroerozivní obrábění", "evidence": "\\"Elektroerozivní obrábění\\""}, {"activity": "CNC broušení a výroba nástrojů", "evidence": "\\"CNC broušení a výroba nástrojů\\""}, {"activity": "Výroba dílců z oceli třídy 11 - 19, neželezných kovů a plastů", "evidence": "\\"Výroba dílců z oceli třídy 11 - 19, neželezných kovů a plastů\\""}, {"activity": "CNC soustružení", "evidence": "\\"Soustružnická CNC centra\\", \\"CNC soustruhy\\""}, {"activity": "CNC vrtání a frézování", "evidence": "\\"Vrtací a frézovací CNC centra\\", \\"Pětiosé CNC vrtací a frézovací centrum\\""}, {"activity": "Konvenční soustružení a frézování", "evidence": "\\"Konvenční soustruhy a frézky\\""}, {"activity": "Vrtání", "evidence": "\\"Řadové a sloupové vrtačky\\""}, {"activity": "Broušení", "evidence": "\\"Vibrační a odstředivé brusky\\""}, {"activity": "Robotické svařování", "evidence": "\\"Svářecí robotizované pracoviště\\""}, {"activity": "Lisování", "evidence": "\\"Výstředníkové a hydraulické lisy\\""}, {"activity": "Stříhání", "evidence": "\\"Padací nůžky\\""}, {"activity": "Řezání pilou", "evidence": "\\"Pásové a kotoučové NC pily\\""}, {"activity": "Výroba nástrojů", "evidence": "\\"CNC bruska nástrojů\\""}, {"activity": "Elektroerozivní vrtání", "evidence": "\\"Elektroerozivní vrtačka\\""}, {"activity": "Drátové elektroerozivní řezání", "evidence": "\\"Elektroerozivní drátová řezačka\\""}, {"activity": "Hloubící elektroerozivní obrábění", "evidence": "\\"Elektroerozivní hloubička\\""}]', '[{"tier": "TIER1", "hsCode": "940120", "evidence": "\\"RÁMY HLAVOVÝCH OPĚR V sériové výrobě hlavových opěr...\\"", "reasoning": "Head restraint frames are parts of seats for motor vehicles.", "confidence": "MEDIUM"}, {"tier": "TIER1", "hsCode": "870899", "evidence": "\\"KRYTY ZAVAZADLOVÉHO PROSTORU ... kryt zavazadlového prostoru.\\"", "reasoning": "Luggage compartment covers are parts and accessories of motor vehicles.", "confidence": "MEDIUM"}, {"tier": "TIER1", "hsCode": "870810", "evidence": "\\"rámy loketních opěr\\"", "reasoning": "Armrest frames could be considered parts of bumpers or general